func connect(endpoint: String, prefix: String) async {
  guard !busy else { return }
  busy = true
  cancelPendingWaypoint()
  sessionEpoch &+= 1
  let epoch = sessionEpoch
  error = nil
  stopObservation()
  clearInput()
  await backend.disconnect()
  clearSessionState()
  defer { busy = false }
  do {
    try await backend.connect(endpoint: endpoint, prefix: prefix)
    guard epoch == sessionEpoch else { return }
    await refresh()
    startObservation()
  } catch {
    guard epoch == sessionEpoch else { return }
    self.error = error.localizedDescription
    await refresh()
  }
}

func refresh() async {
  let epoch = sessionEpoch
  refreshSequence &+= 1
  let request = refreshSequence
  let snapshotCapturedAt = ContinuousClock.now
  var nextSnapshot = await backend.snapshot()
  guard epoch == sessionEpoch, !Task.isCancelled else { return }
  let payloads = await backend.telemetryPayloads()
  guard epoch == sessionEpoch, !Task.isCancelled else { return }
  // JSON parsing and large grid/cloud allocations must not block gestures or
  // native controls. Only apply a completed decode to its original session.
  let decoded = await Task.detached(priority: .userInitiated) {
    payloads.decode()
  }.value
  guard epoch == sessionEpoch, !Task.isCancelled, request > appliedRefreshSequence else { return }
  appliedRefreshSequence = request
  let decodedTelemetry = decoded.aged(by: telemetryElapsed(since: payloads.capturedAt))
  let snapshotElapsed = telemetryElapsed(since: snapshotCapturedAt)
  nextSnapshot.fleetAge = nextSnapshot.fleetAge.map { advancedTelemetryAge($0, by: snapshotElapsed) }
  nextSnapshot.rovers = nextSnapshot.rovers.map { value in
    var rover = value
    rover.poseAge = rover.poseAge.map { advancedTelemetryAge($0, by: snapshotElapsed) }
    rover.goalAge = rover.goalAge.map { advancedTelemetryAge($0, by: snapshotElapsed) }

export async function api<T>(path:string,user?:Identity,method='GET',body?:unknown):Promise<T>{
  const response=await fetch(`/api/v1${path}`,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','x-argos-client':clientID,...(user?{'x-csrf-token':user.csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});
  if(!response.ok){const message=await response.json().catch(()=>({error:`Request failed (${response.status})`}));throw new ApiError(response.status,message.error??`Request failed (${response.status})`)}
  if(response.status===204)return undefined as T;
  return response.json() as Promise<T>;

export function scenePoint(p:Point,r:Rover,f:SceneFrame):Point|null{
  if(f.reference&&r.reference)return local(geographic(p,r.reference),f.reference);
  if(!f.reference&&(r.id===f.owner||(f.frameId!==null&&r.frame_id===f.frameId)))return p;
  return null;
}

export function geographic(p:{x:number;y:number},r:Reference){
  const x=p.x-r.anchor_x,y=p.y-r.anchor_y;
  const north=Math.cos(r.rotation)*x-Math.sin(r.rotation)*y;
  const west=Math.sin(r.rotation)*x+Math.cos(r.rotation)*y;
  return {latitude:r.latitude+north/scale,longitude:r.longitude-west/(scale*Math.cos(r.latitude*Math.PI/180))};
}

