    let config = Config::load().map_err(std::io::Error::other)?;
    let store = Store::open(&config.database).await?;
    let listener = tokio::net::TcpListener::bind(config.bind).await?;
    tracing::info!(bind=%config.bind,demo=config.demo,"ARGOS web service starting");
    let state = AppState::new(config, store)
        .await
        .map_err(std::io::Error::other)?;
    let worker = state.worker.clone();
    let shutdown_worker = worker.clone();
    axum::serve(listener, router(state))
        .with_graceful_shutdown(async move {
            shutdown_signal().await;
            shutdown_worker.stop();
        })
        .await?;
    worker.stop();
    Ok(())

pub fn load() -> Result<Self, String> {
    let get = |key: &str, default: &str| std::env::var(key).unwrap_or_else(|_| default.into());
    let args = std::env::args().collect::<Vec<_>>();
    let production = get("ARGOS_ENV", "development") == "production";
    let dev_auth =
        args.iter().any(|a| a == "--dev") || get("ARGOS_DEV_AUTH", "false") == "true";
    let demo = args.iter().any(|a| a == "--demo") || get("ARGOS_FLEET", "demo") == "demo";
    let mut allowed = BTreeMap::new();
    for (key, role) in [("ARGOS_VIEWERS", "viewer"), ("ARGOS_OPERATORS", "operator")] {
        for id in get(key, "")
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            id.parse::<u64>()
                .map_err(|_| format!("{key} must contain numeric GitHub IDs"))?;
            allowed.insert(id.into(), role.into());
        }
    }
    let config = Self {
        bind: get("ARGOS_BIND", "127.0.0.1:8080")
            .parse()
            .map_err(|_| "Invalid ARGOS_BIND")?,
        origin: get("ARGOS_ORIGIN", "http://127.0.0.1:5173")
            .trim_end_matches('/')
            .into(),
        production,
        dev_auth,
        demo,
        endpoint: get("ARGOS_ZENOH_ENDPOINT", "tcp/127.0.0.1:7448"),
        prefix: get("ARGOS_ZENOH_PREFIX", "terra/rover"),
        database: get("ARGOS_DATABASE", "sqlite://argos.db"),
        web_dir: get("ARGOS_WEB_DIR", "apps/web/dist"),
        github_client: get("GITHUB_CLIENT_ID", ""),
        github_secret: get("GITHUB_CLIENT_SECRET", ""),
        allowed,
        tile_style: std::env::var("ARGOS_TILE_STYLE")
            .ok()
            .filter(|s| !s.is_empty()),
    };
    config.validate()?;
    Ok(config)

pub async fn new(config: Config, store: Store) -> Result<Self, String> {
    config.validate()?;
    let fleet: Box<dyn Fleet> = if config.demo {
        Box::new(DemoFleet::default())
    } else {
        Box::new(LiveFleet::new(
            config.endpoint.clone(),
            config.prefix.clone(),
        ))
    };
    let worker = Worker::start(fleet, store.clone()).await?;
    Ok(Self {
        config: Arc::new(config),
        store,
        worker,
        http: reqwest::Client::builder()
            .timeout(Duration::from_secs(10))
            .build()
            .map_err(|e| e.to_string())?,
    })
}

pub async fn open(url: &str) -> Result<Self, sqlx::Error> {
    let options = SqliteConnectOptions::from_str(url)?
        .create_if_missing(true)
        .journal_mode(SqliteJournalMode::Wal)
        .busy_timeout(Duration::from_secs(5));
    let pool = SqlitePoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await?;
    // Versioned additive schema. Never store live telemetry as authoritative state.
    sqlx::raw_sql(include_str!("schema.sql"))
        .execute(&pool)
        .await?;
    Ok(Self { pool })
}

pub async fn identity(
    headers: &HeaderMap,
    store: &Store,
    config: &Config,
) -> Result<(Identity, i64), StatusCode> {
    let token = cookie(headers, "argos_session").ok_or(StatusCode::UNAUTHORIZED)?;
    let row = sqlx::query(
        "SELECT user_id,login,csrf,expires FROM sessions WHERE token_hash=? AND expires>?",
    )
    .bind(hash(&token))
    .bind(epoch())
    .fetch_optional(&store.pool)
    .await
    .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?
    .ok_or(StatusCode::UNAUTHORIZED)?;
    let id: String = row.get("user_id");
    let role = config.role(&id).ok_or(StatusCode::FORBIDDEN)?;
    Ok((
        Identity {
            id,
            login: row.get("login"),
            csrf: row.get("csrf"),
            role,
        },
        row.get("expires"),
    ))
}

