    let mut port = 7448;
    let mut address = String::new();
    let mut config_file = None;
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--config" => config_file = Some(args.next().ok_or("Missing config path")?),
            "--port" => port = args.next().ok_or("Missing port")?.parse()?,
            "--bind" | "--tailscale-address" => address = args.next().ok_or("Missing address")?,
            "--help" => {
                println!(
                    "argos-router [--config /path/to/zenoh.json5] [--port 7448] [--bind 0.0.0.0 | --tailscale-address 100.x.y.z]"
                );
                return Ok(());
            }
            _ => return Err(format!("Unknown option: {arg}").into()),
        }
    }
    if let Some(path) = config_file {
        use zenoh::Wait;
        let session = zenoh::open(zenoh::Config::from_file(path)?).wait()?;
        while !session.is_closed() {
            std::thread::sleep(std::time::Duration::from_secs(1));
        }
        return Ok(());
    }
    let router = Router::default();
    router.start(port, &address)?;
    for line in router.logs() {
        println!("{line}");
    }
    while router.running() {
        std::thread::sleep(std::time::Duration::from_secs(1));
    }
    Ok(())

pub fn start(&self, port: u16, private_address: &str) -> Result<()> {
    let mut state = self.session.lock().unwrap();
    if state.is_some() {
        return Err(Error(
            "Router already running; stop it before changing its bind".into(),
        ));
    }
    let addresses = listen_addresses(port, private_address)?;
    // Probe every requested bind, then release probes immediately before Zenoh binds.
    let probes: std::io::Result<Vec<_>> = addresses.iter().map(TcpListener::bind).collect();
    let probes = probes.map_err(|e| { self.log(format!("Bind failed: {e}")); Error(format!("Router bind failed: {e}. An existing router may own this port; use Remote host to connect without managing it.")) })?;
    drop(probes);
    let endpoints: Vec<_> = addresses.iter().map(|a| format!("tcp/{a}")).collect();
    let mut config = zenoh::Config::default();
    for (key, value) in [
        ("mode", "\"router\"".to_owned()),
        (
            "listen/endpoints",
            serde_json::to_string(&endpoints).unwrap(),
        ),
        ("scouting/multicast/enabled", "false".into()),
        ("scouting/gossip/enabled", "false".into()),
    ] {
        config
            .insert_json5(key, &value)
            .map_err(|e| Error(e.to_string()))?;
    }
    let session = zenoh::open(config).wait().map_err(|e| {
        self.log(format!("Start failed: {e}"));
        Error(e.to_string())
    })?;
    self.log(format!("Listening on {}", endpoints.join(", ")));
    *state = Some(session);
    Ok(())
}

async fn user(s: &AppState, h: &HeaderMap) -> Result<(Identity, i64), ApiError> {
    auth::identity(h, &s.store, &s.config)
        .await
        .map_err(|c| error(c, "Sign in with an invited account"))
}

fn mutation(s: &AppState, h: &HeaderMap, u: &Identity) -> Result<(), ApiError> {
    if h.get(header::ORIGIN).and_then(|v| v.to_str().ok()) != Some(s.config.origin.as_str())
        || h.get("x-csrf-token").and_then(|v| v.to_str().ok()) != Some(u.csrf.as_str())
    {
        return Err(error(
            StatusCode::FORBIDDEN,
            "Origin and CSRF validation required",
        ));
    }
    Ok(())
}

async fn dispatch(
    s: &AppState,
    h: &HeaderMap,
    action: Action,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (u, _) = user(s, h).await?;
    mutation(s, h, &u)?;
    if u.role != "operator" {
        return Err(error(StatusCode::FORBIDDEN, "Operator role required"));
    }
    let tab = client(h)?;
    let owner = owner(h, &u, &tab);
    s.worker
        .request(u, owner, action)
        .await
        .map(Json)
        .map_err(|e| error(StatusCode::CONFLICT, &e))
}

async fn events(
    State(s): State<AppState>,
    h: HeaderMap,
    Query(q): Query<EventQuery>,
) -> Result<impl IntoResponse, ApiError> {
    let (u, expires) = user(&s, &h).await?;
    if q.client.is_empty()
        || q.client.len() > 64
        || !q
            .client
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-')
    {
        return Err(error(StatusCode::BAD_REQUEST, "Invalid client ID"));
    }
    let owner = owner(&h, &u, &q.client);
    let mut rx = s.worker.snapshots.clone();
    let guard = StreamGuard {
        worker: s.worker.clone(),
        user: u,
        owner,
    };
    let stream = async_stream::stream! {
        let _guard=guard;
        let deadline=tokio::time::sleep(Duration::from_secs((expires-auth::epoch()).max(0) as u64));tokio::pin!(deadline);
        loop {
            if auth::identity(&h,&s.store,&s.config).await.is_err() {break;}
            let snap=rx.borrow_and_update().clone();
            yield Ok::<_,Infallible>(Event::default().event("fleet").json_data(snap).unwrap_or_else(|_|Event::default().event("error").data("Snapshot unavailable")));
            tokio::select! {_= &mut deadline=>break, changed=rx.changed()=>if changed.is_err(){break}}
        }
    };
    Ok(Sse::new(stream).keep_alive(KeepAlive::new().interval(Duration::from_secs(10))))
}

