fn send_goal(&mut self, id: &str, goal: &Waypoint) -> Result<String, String> {
    let r = self
        .rovers
        .iter_mut()
        .find(|r| r.id == id)
        .ok_or("Unknown rover")?;
    let (x, y) = match *goal {
        Waypoint::Local { x, y, .. } => (x, y),
