            latitude,
            longitude,
            ..
        } => {
            let a = r.reference.as_ref().ok_or("Missing geographic reference")?;
            argos_core::Anchor {
                latitude: a.latitude,
                longitude: a.longitude,
            }
            .local(latitude, longitude)
            .map_err(|e| e.to_string())?
        }
    };
    let from = r.pose.clone().ok_or("Missing pose")?;
    let token = uuid::Uuid::new_v4().to_string();
    r.goal = Some(Goal {
        state: "active".into(),
        token: Some(token.clone()),
        x,
        y,
        distance: (x - from.x).hypot(y - from.y),
    });
    r.goal_age = Some(0.);
    r.goal_observation = Some(uuid::Uuid::new_v4().to_string());
    self.goals.retain(|(i, ..)| i != id);
    self.goals
        .push((id.into(), self.now, from, Pose { x, y, yaw: 0. }));
    Ok(token)
}

pub fn connect_authenticated(
    endpoint: &str,
    prefix: &str,
    credentials: Option<(&str, &str)>,
) -> Result<Self> {
    let topics = Topics::new(prefix)?;
    if endpoint.len() > 512
        || !(endpoint.starts_with("tcp/") || endpoint.starts_with("tls/"))
        || endpoint.parse::<zenoh::config::EndPoint>().is_err()
    {
        return Err(invalid(
            "endpoint must be a valid tcp/host:port or tls/host:port",
        ));
    }
    let mut config = zenoh::Config::default();
    config
        .insert_json5("mode", "\"client\"")
        .map_err(|e| Error(e.to_string()))?;
    config
        .insert_json5(
            "connect/endpoints",
            &serde_json::to_string(&vec![endpoint]).unwrap(),
        )
        .map_err(|e| Error(e.to_string()))?;
    config
        .insert_json5("scouting/multicast/enabled", "false")
        .map_err(|e| Error(e.to_string()))?;
    config
        .insert_json5("connect/timeout_ms", "3000")
        .map_err(|e| Error(e.to_string()))?;
    if let Some((user, password)) = credentials {
        for (key, value) in [
            ("transport/auth/usrpwd/user", user),
            ("transport/auth/usrpwd/password", password),
        ] {
            config
                .insert_json5(key, &serde_json::to_string(value).unwrap())
                .map_err(|e| Error(e.to_string()))?;
        }
    }
    let session = zenoh::open(config)
        .wait()
        .map_err(|e| Error(format!("could not connect: {e}")))?;
    let cache = Arc::new(Mutex::new(FleetCache::default()));
    let start = Instant::now();
    let fleet_cache = cache.clone();
    let fleet = session
        .declare_subscriber(topics.fleet())
        .callback(move |sample| {
            let payload = sample.payload().to_bytes();
            let mut cache = fleet_cache.lock().unwrap();
            match decode_fleet(&payload) {
                Ok(f) => cache.fleet(f, start.elapsed().as_secs_f64()),
                Err(e) => cache.notice(e.to_string()),
            }
        })
        .wait()
        .map_err(|e| Error(e.to_string()))?;

std::thread::spawn(move || {
    let mut last: Option<u64> = None;
    while !stop.load(std::sync::atomic::Ordering::Acquire) {
        let now = start.elapsed().as_secs_f64();
        let mut input = held.lock().unwrap();
        let active = input.rover_id.filter(|id| {
            let authority = authority_cache.lock().unwrap();
            let permitted = authority.can_drive(*id, now)
                && input
                    .authority_generation
                    .as_ref()
                    .is_none_or(|(run, revision)| {
                        authority.matches_authority(*id, run, *revision)
                    });
            drop(authority);
            permitted && fleet_cache.lock().unwrap().snapshot(now).link == "healthy"
        });
        if active.is_none() {
            input.rover_id = None;
            input.keys.clear();
        }
        let sample = input.keys.sample();
        if let Some(id) = active {
            if sample != (0., 0.) || last.is_some() {
                let sequence = packet_sequence
                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed)
                    + 1;
                let payload = serde_json::json!({
                    "linear": sample.0,
                    "angular": sample.1,
                    "operator_session_id": callback_session_id,
                    "sequence": sequence,
                    "run_id": input.authority_generation.as_ref().map(|g|&g.0),
                    "authority_revision": input.authority_generation.as_ref().map(|g|g.1),
                });
                if let Some(s) = session.lock().unwrap().as_ref() {
                    let _ = s
                        .put(format!("{prefix}/{id}/teleop"), payload.to_string())
                        .wait();
                }
                let _ = log.record(serde_json::json!({
                    "kind": "teleop_sent",
                    "rover_id": id,
                    "time": now,
                    "utc": utc(),
                    "sequence": sequence,
                    "session_id": callback_session_id,
                    "payload": payload,
                }));
                last = if sample == (0., 0.) { None } else { Some(id) };
            }
        } else if let Some(id) = last.take()
            && let Some(s) = session.lock().unwrap().as_ref()
        {
            let _ = s
                .put(
                    format!("{prefix}/{id}/teleop"),
                    zero_payload(
                        &callback_session_id,
                        &packet_sequence,
                        input.authority_generation.as_ref(),
                    ),
                )
                .wait();
        }
        drop(input);
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
})

pub fn snapshot(&self) -> Snapshot {
    self.cache
        .lock()
        .unwrap()
        .snapshot(self.start.elapsed().as_secs_f64())
}

pub fn send_goal(&self, id: u64, goal: GoalRequest) -> Result<String> {
    let _action = self.actions.lock().unwrap();
    let token = uuid::Uuid::new_v4().to_string();
    let payload = self.cache.lock().unwrap().prepare_goal(
        id,
        &goal,
        &token,
        self.start.elapsed().as_secs_f64(),
    )?;
    self.publish(id, payload.clone())?;
    let _ = self.recorder.record(serde_json::json!({
        "kind": "goal_sent",
        "rover_id": id,
        "token": token,
        "time": self.start.elapsed().as_secs_f64(),
        "utc": utc(),
        "session_id": self.session_id,
        "payload": serde_json::from_slice::<serde_json::Value>(&payload).ok(),
    }));
    Ok(token)
}

fn publish(&self, id: u64, payload: Vec<u8>) -> Result<()> {
    let session = self.session.lock().unwrap();
    let result = session
        .as_ref()
        .ok_or_else(|| invalid("disconnected"))
        .and_then(|s| {
            s.put(self.topics.goal(id), payload)
                .wait()
                .map_err(|e| Error(e.to_string()))
        });
    if let Err(e) = &result {
        self.cache.lock().unwrap().publish_failed(id, e.to_string());
    }
    result
}

pub fn cancel_goal(&self, id: u64) -> Result<()> {
    let _action = self.actions.lock().unwrap();
    self.cache
        .lock()
        .unwrap()
        .prepare_cancel(id, self.start.elapsed().as_secs_f64())?;
    let _ = self.recorder.record(serde_json::json!({
        "kind": "goal_cancel_sent",
        "rover_id": id,
        "time": self.start.elapsed().as_secs_f64(),
        "utc": utc(),
        "session_id": self.session_id,
    }));
    self.publish(id, cancel_payload().to_vec())
}

pub fn operator_command(&self, id: u64, kind: &str, payload: &str) -> Result<()> {
    let _action = self.actions.lock().unwrap();
    if !matches!(
        kind,
        "autonomy"
            | "teleop"
            | "hardware"
            | "navigation/settings"
            | "search"
            | "search/action"
            | "search/report/ack"
    ) || payload.len() > 2048
    {
        return Err(invalid("invalid operator command"));
    }

pub fn occupancy_grid(&self, id: u64) -> Option<(OccupancyGrid, f64, Option<String>)> {
    self.maps.lock().unwrap().get(&id).map(|(grid, at, frame)| {
        (
            grid.clone(),
            (self.start.elapsed().as_secs_f64() - at).max(0.),
            frame.clone(),
        )
    })
}

pub fn occupancy_snapshot(&self) -> String {
    self.occupancy_snapshot_value().to_string()
}
fn occupancy_snapshot_value(&self) -> serde_json::Value {
    let now = self.start.elapsed().as_secs_f64();
    let fleet = self.cache.lock().unwrap().snapshot(now);
    // Copy a coherent set of typed grids under the lock; expanding cells into
    // JSON values and serializing the public wire payload happen afterwards.
    let grids: Vec<_> = {
        let maps = self.maps.lock().unwrap();
        fleet
            .rovers
            .iter()
            .filter(|r| r.membership != "absent")
            .filter_map(|rover| {
                maps.get(&rover.id)
                    .map(|(grid, time, _)| (rover.id, grid.clone(), (now - time).max(0.)))
            })
            .collect()
    };
    let mut result = serde_json::Map::new();
    for (id, grid, age) in grids {
        result.insert(id.to_string(), serde_json::json!({"grid": grid,"age": age}));
    }
    serde_json::Value::Object(result)
}

pub fn operator_state_snapshot(&self) -> String {
    let mut result = self.legacy_operator_snapshot_value();
    for ((id, kind), (value, received)) in self.operator_states.lock().unwrap().iter() {
        let age = received.elapsed().as_secs_f64();
        let max_age = if kind == "authority" || kind == "hardware" {
            SUPERVISION_STALE_SECONDS
        } else {
            2.5
        };
        if age >= max_age {
            continue;
        }
        let mut value = value.clone();
        value["age"] = serde_json::json!(age);
        if kind.starts_with("search_report:") {
            if !result[id.to_string()]["reports"].is_array() {
                result[id.to_string()]["reports"] = serde_json::json!([]);
            }
            result[id.to_string()]["reports"]
                .as_array_mut()
                .unwrap()
                .push(value);
        } else {
            result[id.to_string()][kind] = value;
        }
    }
    result.to_string()
}

pub fn localization_snapshot(&self) -> String {
    let values: serde_json::Map<String, serde_json::Value> = self
        .localizations
        .lock()
        .unwrap()
        .iter()
        .filter_map(|(id, (value, received))| {
            let age = received.elapsed().as_secs_f64();
            if age >= SUPERVISION_STALE_SECONDS {
                return None;
            }
            let mut value = value.clone();
            value["age"] = serde_json::json!(age);
            Some((id.to_string(), value))
        })
        .collect();
    serde_json::Value::Object(values).to_string()
}

pub fn action(&self, id: u64, kind: &str, value: serde_json::Value) -> Result<String> {
    let token = uuid::Uuid::new_v4().to_string();
    let payload = operator_payload(kind, value, &token)?;
    if kind == "autonomy" || kind == "safety" {
        self.clear_input();
    }
    let now = self.start.elapsed().as_secs_f64();
    if kind != "mission/report" {
        self.operator
            .lock()
            .unwrap()
            .pending(id, token.clone(), now);
    }
    let session = self.session.lock().unwrap();
    let s = session.as_ref().ok_or_else(|| invalid("disconnected"))?;
    s.put(
        format!("{}/{id}/{kind}", self.topics.prefix),
        payload.clone(),
    )
    .wait()
    .map_err(|e| Error(e.to_string()))?;
    let _ = self.recorder.record(serde_json::json!({
        "kind": "action_sent",
        "rover_id": id,
        "token": token,
        "topic": kind,
        "time": now,
        "utc": utc(),
        "session_id": self.session_id,
        "payload": serde_json::from_slice::<serde_json::Value>(&payload).unwrap(),
    }));
    Ok(token)
}

pub fn input_generation(
    &self,
    id: u64,
    key: &str,
    down: bool,
    sequence: u64,
    run: &str,
    revision: u64,
) -> Result<()> {
    let mut order = self.ui_sequence.lock().unwrap();
    if !order.accept(key, sequence) {
        return Ok(());
    }
    self.input_checked(id, key, down, Some((run, revision)))
}

fn input_checked(
    &self,
    id: u64,
    key: &str,
    down: bool,
    generation: Option<(&str, u64)>,
) -> Result<()> {
    let now = self.start.elapsed().as_secs_f64();
    let mut held = self.held.lock().unwrap();
    let accepted_generation = {
        let authority = self.operator.lock().unwrap();
        if generation
            .is_some_and(|(run, revision)| !authority.matches_authority(id, run, revision))
        {
            return Ok(());
        }
        if down && !authority.can_drive(id, now) {
            return Err(invalid("fresh confirmed teleop authority required"));
        }
        authority.generation(id)
    };
    if held.rover_id != Some(id) {
        if let Some(previous) = held.rover_id
            && let Some(s) = self.session.lock().unwrap().as_ref()
        {
            let _ = s
                .put(
                    format!("{}/{previous}/teleop", self.topics.prefix),
                    zero_payload(
                        &self.session_id,
                        &self.teleop_sequence,
                        held.authority_generation.as_ref(),
                    ),
                )
                .wait();
        }
        held.keys.clear();
    }
    held.rover_id = Some(id);
    held.authority_generation = accepted_generation;
    if down {
        held.keys.press(key);
    } else {
        held.keys.release(key);
    }
    Ok(())
}

pub fn new(prefix: &str) -> Result<Self> {
    let p = prefix.trim().trim_matches('/');
    if p.is_empty()
        || p.len() > 256
        || p.split('/').any(str::is_empty)
        || p.chars().any(|c| c.is_whitespace() || "*?#$".contains(c))
    {
        return Err(invalid("prefix must be a concrete Zenoh key"));
    }
    Ok(Self { prefix: p.into() })
}
pub fn goal(&self, id: u64) -> String {
    format!("{}/{id}/goal", self.prefix)
}
pub fn fleet(&self) -> String {
    format!("{}/fleet/state", self.prefix)
}
pub fn statuses(&self) -> String {
    format!("{}/*/goal/status", self.prefix)
}
pub fn depth(&self) -> String {
    format!("{}/*/camera/depth", self.prefix)
}
pub fn rover_from_key(&self, key: &str, suffix: &str) -> Option<u64> {
    key.strip_prefix(&format!("{}/", self.prefix))?
        .strip_suffix(suffix)?
        .parse()
        .ok()
}

    pub fn encode(&self, token: &str) -> Result<Vec<u8>> {
        if !valid_token(token) {
            return Err(invalid("invalid goal token"));
        }
        let (mut value, yaw) = match *self {
            Self::Local { x, y, yaw } => {
                if !x.is_finite() || !y.is_finite() || x.abs() > 20_000. || y.abs() > 20_000. {
                    return Err(invalid(
                        "local coordinates must be finite and within 20000 metres",
                    ));
                }
                (json!({"frame": "local","x": x,"y": y}), yaw)
            }
            Self::Geographic {
                latitude,
                longitude,
                yaw,
            } => {
                if !latitude.is_finite()
                    || !longitude.is_finite()
                    || !(-85. ..=85.).contains(&latitude)
                    || !(-180. ..=180.).contains(&longitude)
                {
                    return Err(invalid("geographic coordinates outside Terra bounds"));
                }
                (
                    json!({"frame": "wgs84","latitude": latitude,"longitude": longitude}),
                    yaw,
                )
            }
        };
        if let Some(yaw) = yaw {
            if !yaw.is_finite() || yaw.abs() > std::f64::consts::TAU {
                return Err(invalid("yaw must be within +/-2pi"));
            }
            value["yaw"] = json!(yaw);
        }
        value["token"] = json!(token);
        let bytes = serde_json::to_vec(&value).map_err(|e| Error(e.to_string()))?;
        if bytes.len() > 2048 {
            return Err(invalid("goal exceeds 2048 bytes"));
        }
        Ok(bytes)
    }
}

pub fn decode_fleet(bytes: &[u8]) -> Result<FleetState> {
    let f: FleetState = parse(bytes)?;
    if f.ids.len() > 4096 || f.ids.iter().collect::<BTreeSet<_>>().len() != f.ids.len() {
        return Err(invalid("invalid or duplicate fleet ids"));
    }
    Ok(f)
}

pub fn decode_status(bytes: &[u8]) -> Result<GoalStatus> {
    let s: GoalStatus = parse(bytes)?;
    if !s.distance.is_finite()
        || s.distance < 0.
        || !s.x.is_finite()
        || !s.y.is_finite()
        || (s.state == GoalState::Idle) != (s.goal_id == 0)
        || s.token.as_ref().is_some_and(|t| !valid_token(t))
        || s.yaw
            .is_some_and(|v| !v.is_finite() || v.abs() > std::f64::consts::TAU)
        || s.latitude.is_some() != s.longitude.is_some()
        || s.latitude
            .is_some_and(|v| !v.is_finite() || !(-85. ..=85.).contains(&v))
        || s.longitude
            .is_some_and(|v| !v.is_finite() || !(-180. ..=180.).contains(&v))
    {
        return Err(invalid("invalid goal status values"));
    }
    Ok(s)
}

pub fn decode_pose(bytes: &[u8]) -> Result<Option<Pose>> {
    let split = bytes
        .iter()
        .take(MAX_STATE_BYTES + 1)
        .position(|b| *b == b'\n')
        .filter(|n| *n <= MAX_STATE_BYTES)
        .ok_or_else(|| invalid("missing or oversized depth header"))?;
    let h: Value =
        serde_json::from_slice(&bytes[..split]).map_err(|e| crate::Error(e.to_string()))?;
    if h["version"].as_u64() != Some(1) || h["encoding"].as_str() != Some("32FC1_LE") {
        return Err(invalid("unsupported depth packet"));
    }
    let id = h["rover_id"]
        .as_u64()
        .ok_or_else(|| invalid("invalid depth rover id"))?;
    let sequence = h["sequence"]
        .as_u64()
        .ok_or_else(|| invalid("invalid depth sequence"))?;
    let Some(body) = h.get("body") else {
        return Ok(None);
    };
    Ok(Some(Pose {
        rover_id: id,
        sequence,
        x: finite(body.get("x"))?,
        y: finite(body.get("y"))?,
        yaw: finite(body.get("yaw"))?,
    }))
}

pub fn decode_body_pose(bytes: &[u8]) -> Result<Pose> {
    if bytes.len() > MAX_STATE_BYTES {
        return Err(invalid("oversized pose"));
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|_| invalid("invalid pose JSON"))?;
    Ok(Pose {
        rover_id: value["rover_id"]
            .as_u64()
            .ok_or_else(|| invalid("missing rover ID"))?,
        sequence: value["sequence"]
            .as_u64()
            .ok_or_else(|| invalid("missing pose sequence"))?,
        x: finite(value.get("x"))?,
        y: finite(value.get("y"))?,
        yaw: finite(value.get("yaw"))?,
    })
}

pub fn decode_occupancy(bytes: &[u8]) -> Result<OccupancyGrid> {
    if bytes.len() > 2_000_000 {
        return Err(invalid("oversized occupancy grid"));
    }
    let grid: OccupancyGrid =
        serde_json::from_slice(bytes).map_err(|_| invalid("invalid occupancy JSON"))?;
    let cells = u64::from(grid.width) * u64::from(grid.height);
    if grid.schema_version != 1
        || grid.run_id.is_empty()
        || grid.run_id.len() > 256
        || cells == 0
        || cells > 250_000
        || cells != grid.occupancy.len() as u64
        || !grid.resolution.is_finite()
        || grid.resolution <= 0.
        || !grid.origin_x.is_finite()
        || !grid.origin_y.is_finite()
        || !(grid.origin_x + f64::from(grid.width) * grid.resolution).is_finite()
        || !(grid.origin_y + f64::from(grid.height) * grid.resolution).is_finite()
        || grid.occupancy.iter().any(|v| !(-1..=100).contains(v))
    {
        return Err(invalid("invalid occupancy geometry or cells"));
    }
    Ok(grid)
}

pub fn fleet(&mut self, state: FleetState, now: f64) {
    self.disconnected = false;
    let previous = self
        .fleet
        .as_ref()
        .map(|(fleet, _)| fleet.ids.iter().copied().collect::<BTreeSet<_>>())
        .unwrap_or_default();
    for id in &state.ids {
        let entry = self.entries.entry(*id).or_default();
        if !previous.contains(id) {
            *entry = Entry::default();
        }
    }
    // Terra retires increasing IDs. Preserve current membership plus at most
    // 32 retired rows for last-known inspection, rather than lifetime history.
    let current = state.ids.iter().copied().collect::<BTreeSet<_>>();
    let retired = self
        .entries
        .keys()
        .rev()
        .filter(|id| !current.contains(id))
        .take(32)
        .copied()
        .collect::<BTreeSet<_>>();
    self.entries
        .retain(|id, _| current.contains(id) || retired.contains(id));
    self.notice = (state.count != state.ids.len() as u64)
        .then(|| "Fleet count disagrees with membership".into());
    self.fleet = Some((state, now));
}

pub fn status(&mut self, id: u64, status: GoalStatus, now: f64) {
    if !self.member(id) {
        return;
    }
    let entry = self.entries.entry(id).or_default();
    if let Some(command) = &mut entry.command {
        if command.phase == "cancelling"
            && now > command.sent
            && status.state == GoalState::Idle
        {
            command.phase = "cancelled".into();
        } else if command.token.is_some()
            && command.token == status.token
            && now >= command.sent
        {
            command.phase = match status.state {
                GoalState::Idle => "superseded",
                GoalState::Active => "active",
                GoalState::Arrived => "arrived",
            }
            .into();
        } else if command.phase == "active" {
            command.phase = "superseded".into();
        }
    }
    entry.goal = Some((status, now));
}

pub fn pose(&mut self, id: u64, pose: Pose, now: f64) {
    if self.member(id) && pose.rover_id == id {
        self.entries.entry(id).or_default().pose = Some((pose, now));
    }
}

pub fn snapshot(&self, now: f64) -> Snapshot {
    let fleet_age = self.fleet.as_ref().map(|(_, at)| (now - at).max(0.));
    let link = if self.disconnected {
        "disconnected"
    } else if fleet_age.is_none() {
        "connecting"
    } else if fleet_age.unwrap() >= SUPERVISION_STALE_SECONDS {
        "stale"
    } else {
        "healthy"
    };
    let rovers = self
        .entries
        .iter()
        .map(|(&id, entry)| {
            let command_phase = entry
                .command
                .as_ref()
                .map(|command| {
                    if (command.phase == "pending" || command.phase == "cancelling")
                        && now - command.sent >= GOAL_ACK_SECONDS
                    {
                        "unconfirmed".into()
                    } else {
                        command.phase.clone()
                    }
                })
                .unwrap_or_else(|| "none".into());
            RoverSnapshot {
                id,
                membership: if !self.member(id) {
                    "absent"
                } else if link == "stale" {
                    "stale"
                } else {
                    "online"
                }
                .into(),
                pose: entry.pose.as_ref().map(|(p, _)| p.clone()),
                pose_age: entry.pose.as_ref().map(|(_, at)| (now - at).max(0.)),
                goal: entry.goal.as_ref().map(|(g, _)| g.clone()),
                goal_age: entry.goal.as_ref().map(|(_, at)| (now - at).max(0.)),
                goal_received_at: entry.goal.as_ref().map(|(_, at)| *at),
                command_phase,
                command_token: entry
                    .command
                    .as_ref()
                    .and_then(|command| command.token.clone()),
            }
        })
        .collect();
    Snapshot {
        link: link.into(),
        fleet_age,
        rovers,
        notice: self.notice.clone(),
    }
}

pub fn prepare_goal(
    &mut self,
    id: u64,
    request: &GoalRequest,
    token: &str,
    now: f64,
) -> Result<Vec<u8>> {
    self.ready(id, now)?;
    let bytes = request.encode(token)?;
    let entry = self.entries.entry(id).or_default();
    if entry.command.as_ref().is_some_and(|command| {
        (command.phase == "pending" || command.phase == "cancelling")
            && now - command.sent < GOAL_ACK_SECONDS
    }) {
        return Err(invalid("a command is awaiting acknowledgement"));
    }
    entry.command = Some(Command {
        token: Some(token.into()),
        phase: "pending".into(),
        sent: now,
    });
    Ok(bytes)
}

pub fn prepare_cancel(&mut self, id: u64, now: f64) -> Result<()> {
    self.ready(id, now)?;
    let entry = self.entries.entry(id).or_default();
    if entry.command.as_ref().is_some_and(|command| {
        command.phase == "cancelling" && now - command.sent < GOAL_ACK_SECONDS
    }) {
        return Err(invalid("cancellation is awaiting acknowledgement"));
    }
    entry.command = Some(Command {
        token: None,
        phase: "cancelling".into(),
        sent: now,
    });
    Ok(())
}

pub fn apply(&mut self, id: u64, kind: &str, bytes: &[u8], now: f64) -> Result<()> {
    if bytes.len() > MAX_STATE_BYTES || !now.is_finite() {
        return Err(invalid("invalid operator state"));
    }
    let value: Value =
        serde_json::from_slice(bytes).map_err(|_| invalid("malformed operator state"))?;
    let entry = self.entries.entry(id).or_default();
    if matches!(kind, "autonomy/status" | "experiment/status")
        && let Some(run) = value["run_id"].as_str()
    {
        if entry.retired_runs.contains(run) {
            return Ok(());
        }
        if entry.run_id.as_deref() != Some(run) {
            let mut retired = std::mem::take(&mut entry.retired_runs);
            if let Some(old) = entry.run_id.take() {
                retired.insert(old);
            }
            *entry = OperatorEntry {
                run_id: Some(run.into()),
                retired_runs: retired,
                ..Default::default()
            };
        }
    }
    if kind == "goal/proposal"
        && !value.is_null()
        && entry.run_id.as_deref() != value["run_id"].as_str()
    {
        return Ok(());
    }
    match kind {
        "autonomy/status" => {
            let level = value["requested_level"]
                .as_str()
                .ok_or_else(|| invalid("missing level"))?;
            if !matches!(
                level,
                "teleop"
                    | "assisted_teleop"
                    | "waypoint"
                    | "waypoint_direct"
                    | "supervised"
                    | "target_search"
            ) || value["revision"].as_u64().is_none()
            {
                return Err(invalid("invalid authority"));
            }
            if entry.status.as_ref().is_some_and(|(status, _)| {
                status["revision"].as_u64() > value["revision"].as_u64()
            }) {
                return Ok(());
            }
            if let Some((token, at, phase)) = &mut entry.pending
                && value["token"].as_str() == Some(token)
                && now >= *at
            {
                *phase = value["result"].as_str().unwrap_or("unconfirmed").into();
            }
            entry.status = Some((value, now));
        }
        "goal/proposal" => {
            entry.proposal = if value.is_null() {
                None
            } else {
                if value["proposal_id"].as_u64().is_none()
                    || ["x", "y", "expires_at"]
                        .iter()
                        .any(|k| value[*k].as_f64().is_none_or(|n| !n.is_finite()))
                {
                    return Err(invalid("invalid proposal"));
                }
                Some(value)
            };
        }
        "mission/status" => entry.mission = Some(value),
        "experiment/status" => entry.experiment = Some((value, now)),
        _ => return Err(invalid("unknown state topic")),
    }
    Ok(())

pub fn snapshot(&self, now: f64) -> Value {
    let mut out = serde_json::Map::new();
    for (id, entry) in &self.entries {
        let phase = entry
            .pending
            .as_ref()
            .map(|(_, t, p)| {
                if p == "pending" && now - *t >= 2. {
                    "unconfirmed"
                } else {
                    p.as_str()
                }
            })
            .unwrap_or("none");
        let remaining = entry
            .proposal
            .as_ref()
            .and_then(|p| p["expires_at"].as_f64())
            .zip(
                entry
                    .experiment
                    .as_ref()
                    .and_then(|status| status.0["run_elapsed"].as_f64()),
            )
            .map(|(expiry, elapsed)| {
                expiry
                    - elapsed
                    - entry
                        .experiment
                        .as_ref()
                        .map(|status| now - status.1)
                        .unwrap_or(0.)
            });
        out.insert(
            id.to_string(),
            json!({
                "proposal_remaining": remaining,
                "status": entry.status.as_ref().map(|status|&status.0),
                "age": entry.status.as_ref().map(|status|now-status.1),
                "proposal": entry.proposal,
                "mission": entry.mission,
                "experiment": entry.experiment.as_ref().map(|status|&status.0),
                "action_phase": phase,
                "action_token": entry.pending.as_ref().map(|p|&p.0),
            }),
        );
    }
    Value::Object(out)
}

pub fn operator_payload(kind: &str, mut value: Value, token: &str) -> Result<Vec<u8>> {
    if !valid_token(token) || !value.is_object() {
        return Err(invalid("invalid action"));
    }
    let fields: &[&str] = match kind {
        "autonomy" => {
            if !matches!(
                value["level"].as_str(),
                Some(
                    "teleop"
                        | "assisted_teleop"
                        | "waypoint"
                        | "waypoint_direct"
                        | "supervised"
                        | "target_search"
                )
            ) {
                return Err(invalid("invalid level"));
            }
            &["level"]
        }
        "safety" => {
            if !matches!(value["action"].as_str(), Some("stop" | "reset")) {
                return Err(invalid("invalid safety action"));
            }
            &["action"]
        }
        "goal/decision" => {
            if !matches!(
                value["decision"].as_str(),
                Some("approve" | "reject" | "resume")
            ) {
                return Err(invalid("invalid decision"));
            }
            if value["decision"] != "resume" && value["proposal_id"].as_u64().is_none() {
                return Err(invalid("missing proposal ID"));
            }
            if value["run_id"]
                .as_str()
                .is_none_or(|status| !valid_token(status))
            {
                return Err(invalid("missing run identity"));
            }
            &["decision", "proposal_id", "run_id"]
        }
        "mission/report" => {
            if value["survivor_id"].as_u64().is_none() {
                return Err(invalid("missing survivor ID"));
            }
            &["survivor_id"]
        }
        _ => return Err(invalid("unknown action")),
    };
    if value
        .as_object()
        .unwrap()
        .keys()
        .any(|k| !fields.contains(&k.as_str()))
    {
        return Err(invalid("unexpected action field"));
    }
    value["token"] = token.into();
    serde_json::to_vec(&value).map_err(|entry| Error(entry.to_string()))
}

pub(super) fn refresh_grid(
    cached: &mut (OccupancyGrid, f64, Option<String>),
    heartbeat: &Identity,
    now: f64,
) {
    if cached.0.run_id == heartbeat.frame && cached.0.sequence == heartbeat.sequence {
        cached.1 = now;
    }
}

pub(super) fn refresh_cloud(cached: &mut (Value, Instant), heartbeat: &Identity, now: Instant) {
    if cached.0["version"].as_u64() == Some(1)
        && cached.0["frameID"].as_str() == Some(heartbeat.frame.as_str())
        && cached.0["sequence"].as_u64() == Some(heartbeat.sequence)
    {
        cached.1 = now;
    }
}

